using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Reflection;using System.Management;using System.Diagnostics;
namespace AgentBrowser.Installer {
internal static class InstallerReviewTests {
 static int failures,count;static string root,package;
 static void Assert(bool value,string message){if(!value)throw new Exception(message);}
 static void Case(string name,Action<SetupOptions> action){
  var options=new SetupOptions{PackageDir=package,InstallDir=Path.Combine(root,name),Startup=false,Start=false};
  try{action(options);count++;Console.WriteLine("PASS REVIEW "+name);}catch(Exception error){failures++;Console.WriteLine("FAIL REVIEW "+name+": "+error.GetBaseException().Message);}
  finally{var state=InstallerEngine.State(options.InstallDir);if(state!=null)try{InstallerEngine.Apply(InstallerEngine.Prepare(new SetupOptions{Operation="uninstall",InstallDir=options.InstallDir}),CancellationToken.None,s=>{});}catch(Exception e){Console.WriteLine("REVIEW cleanup: "+e.Message);}}
 }
 static void Apply(SetupOptions options){InstallerEngine.Apply(InstallerEngine.Prepare(options),CancellationToken.None,s=>{});}
 public static int Run(string destination,string source){root=destination;package=source;Directory.CreateDirectory(root);
  foreach(bool enable in new[]{true,false})Case("missing-startup-"+enable,o=>{o.Startup=true;o.StartupDir=Path.Combine(o.InstallDir,"startup");Apply(o);File.Delete(InstallerEngine.State(o.InstallDir).Startup.Path);o.Startup=enable;Apply(o);Assert(File.Exists(Path.Combine(o.StartupDir,"AgentBrowser.lnk"))==enable,"missing owned shortcut did not follow update choice");});
  Case("unicode-shortcut",o=>{string stage=Path.Combine(o.InstallDir,"עברית😀日本語");Directory.CreateDirectory(stage);var method=typeof(InstallerEngine).GetMethod("Shortcut",BindingFlags.NonPublic|BindingFlags.Static);var bytes=(byte[])method.Invoke(null,new object[]{stage,Path.Combine(stage,"target.exe"),stage});Assert(bytes.Length>0,"Unicode shortcut missing");});
  Case("created-settings-removal",o=>{string path=Path.Combine(o.InstallDir,"outside-config.json");o.Registrations.Add(new McpRecord{Kind="windows",Path=path});Apply(o);InstallerEngine.Apply(InstallerEngine.Prepare(new SetupOptions{Operation="uninstall",InstallDir=o.InstallDir}),CancellationToken.None,s=>{});Assert(!File.Exists(path),"installer-created empty settings file remains");});
  Case("created-settings-user-content",o=>{string path=Path.Combine(o.InstallDir,"outside-config.jsonc");o.Registrations.Add(new McpRecord{Kind="windows",Path=path});Apply(o);File.AppendAllText(path,"\n// keep my comment\n",NativeIO.Utf8);InstallerEngine.Apply(InstallerEngine.Prepare(new SetupOptions{Operation="uninstall",InstallDir=o.InstallDir}),CancellationToken.None,s=>{});Assert(File.ReadAllText(path).Contains("// keep my comment"),"uninstall removed a user comment");});
  Case("missing-startup-preview-race",o=>{o.Startup=true;o.StartupDir=Path.Combine(o.InstallDir,"startup");Apply(o);string path=InstallerEngine.State(o.InstallDir).Startup.Path;File.Delete(path);var plan=InstallerEngine.Prepare(o);File.WriteAllText(path,"concurrent user file",NativeIO.Utf8);bool rejected=false;try{InstallerEngine.Apply(plan,CancellationToken.None,s=>{});}catch(IOException){rejected=true;}Assert(rejected&&File.ReadAllText(path)=="concurrent user file","concurrent Startup file was overwritten");File.Delete(path);});
  Case("durable-settings-backup",o=>{string path=Path.Combine(o.InstallDir,"outside-config.jsonc");Directory.CreateDirectory(o.InstallDir);string original="{ // private fixture comment\n\"model\":\"test/original\"}";File.WriteAllText(path,original,NativeIO.Utf8);o.Registrations.Add(new McpRecord{Kind="windows",Path=path});Apply(o);var first=InstallerEngine.State(o.InstallDir).Mcps[0].Backups;Assert(first.Length>0&&File.ReadAllText(first[0])==original,"durable exact pre-edit backup missing");Apply(o);Assert(InstallerEngine.State(o.InstallDir).Mcps[0].Backups.Length==first.Length,"unchanged retry proliferated backups");InstallerEngine.Apply(InstallerEngine.Prepare(new SetupOptions{Operation="uninstall",InstallDir=o.InstallDir}),CancellationToken.None,s=>{});Assert(File.ReadAllText(first[0])==original,"uninstall deleted original backup");Assert(Directory.GetFiles(Path.GetDirectoryName(first[0]),"*.bak").Length==first.Length+1,"uninstall did not retain its pre-edit settings backup");});
  Case("committed-cleanup-warning",o=>{string block=null;var result=InstallerEngine.Apply(InstallerEngine.Prepare(o),CancellationToken.None,s=>{if(block==null&&s.StartsWith("파일 적용")){string stage=Directory.GetDirectories(o.InstallDir,".transaction-*").Single();block=Path.Combine(stage,"fixture-block");Directory.CreateDirectory(block);}});Assert(InstallerEngine.State(o.InstallDir)!=null&&result.Contains("설치 완료")&&result.Contains("경고"),"committed operation was not a success with warning");Directory.Delete(block);Directory.Delete(Path.GetDirectoryName(block));});
  Case("cmd-profile-contract",o=>{Apply(o);string cmd=Path.Combine(o.InstallDir,"OpenCode & fixture.cmd");File.WriteAllText(cmd,"@echo off\r\necho 1.18.29\r\n",NativeIO.Utf8);bool rejected=false;try{ManagedProfile.Prepare(InstallerEngine.State(o.InstallDir),new OpenCodeCandidate{Kind="windows",Executable=cmd},"restricted-cmd","Restricted",o.InstallDir);}catch(IOException){rejected=true;}Assert(rejected,"GUI validation accepted a path rejected by Bridge save");});
  Case("startup-pid-publication-failure",o=>{
   var tcp=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);tcp.Start();o.Port=((System.Net.IPEndPoint)tcp.LocalEndpoint).Port;tcp.Stop();o.Start=true;
   var plan=InstallerEngine.Prepare(o);string exe=plan.Next.CurrentExe;DateTime started=DateTime.UtcNow.AddSeconds(-1);bool rejected=false;int live=0;
   try{try{InstallerEngine.Apply(plan,CancellationToken.None,s=>{if(s.StartsWith("Bridge "))Directory.CreateDirectory(Path.Combine(o.InstallDir,"data","serve.pid"));});}catch{rejected=true;}
    using(var query=new ManagementObjectSearcher("SELECT ProcessId,ExecutablePath,CreationDate FROM Win32_Process WHERE Name='browser-bridge.exe'"))foreach(ManagementObject item in query.Get())using(item){if(!String.Equals(item["ExecutablePath"] as string,exe,StringComparison.OrdinalIgnoreCase))continue;DateTime created=ManagementDateTimeConverter.ToDateTime((string)item["CreationDate"]).ToUniversalTime();if(created<started)continue;live++;using(var process=Process.GetProcessById(Convert.ToInt32(item["ProcessId"]))){Assert(Math.Abs((process.StartTime.ToUniversalTime()-created).TotalMilliseconds)<2,"fixture child identity changed");process.Kill();process.WaitForExit(5000);}}
    Assert(rejected&&live==0,"post-start PID failure left "+live+" owned child process(es)");
   }finally{string marker=Path.Combine(o.InstallDir,"data","serve.pid");if(Directory.Exists(marker))Directory.Delete(marker);}
  });
  Console.WriteLine("REVIEW "+count+" PASS, "+failures+" FAIL");if(failures>0)throw new Exception("Installer review regressions failed");return count;
 }
}
}
